+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.RouterLink;
+import com.vaadin.flow.router.Route;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[\\w+.-]+@[\\w-]+(\\.[\\w-]+)+$");
+    private static final int MAX_MESSAGE_LENGTH = 500;
+
+    private final ContactMessageService messageService;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+
+    private final Grid<ContactMessage> grid = new Grid<>(ContactMessage.class, false);
+
+    public ContactView(ContactMessageService messageService) {
+        this.messageService = messageService;
+
+        add(new H1("Contact"));
+        add(new RouterLink("About", AboutView.class));
+
+        send.addClickListener(e -> trySend());
+        send.addClickShortcut(Key.ENTER);
+
+        name.addValueChangeListener(e -> send.setEnabled(true));
+        email.addValueChangeListener(e -> send.setEnabled(true));
+        phone.addValueChangeListener(e -> send.setEnabled(true));
+        message.addValueChangeListener(e -> send.setEnabled(true));
+
+        add(new VerticalLayout(name, email, phone, message, send));
+
+        grid.addColumn(ContactMessage::name).setHeader("Name");
+        grid.addColumn(ContactMessage::message).setHeader("Message");
+        add(grid);
+
+        refreshGrid();
+    }
+
+    private void trySend() {
+        if (!validate()) {
+            return;
+        }
+
+        ContactMessage sent = new ContactMessage(name.getValue(), email.getValue(), phone.getValue(),
+                message.getValue());
+        messageService.add(sent);
+        refreshGrid();
+
+        Notification.show("Message sent");
+
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        send.setEnabled(false);
+    }
+
+    private boolean validate() {
+        boolean valid = true;
+
+        name.setInvalid(false);
+        email.setInvalid(false);
+        message.setInvalid(false);
+
+        if (name.getValue().isBlank()) {
+            name.setInvalid(true);
+            name.setErrorMessage("Name is required");
+            valid = false;
+        }
+
+        String emailValue = email.getValue();
+        String phoneValue = phone.getValue();
+        if (!emailValue.isBlank() && !EMAIL_PATTERN.matcher(emailValue).matches()) {
+            email.setInvalid(true);
+            email.setErrorMessage("Enter a valid e-mail address");
+            valid = false;
+        } else if (emailValue.isBlank() && phoneValue.isBlank()) {
+            email.setInvalid(true);
+            email.setErrorMessage("Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        String messageValue = message.getValue();
+        if (messageValue.isBlank()) {
+            message.setInvalid(true);
+            message.setErrorMessage("Message is required");
+            valid = false;
+        } else if (messageValue.length() > MAX_MESSAGE_LENGTH) {
+            message.setInvalid(true);
+            message.setErrorMessage("Message must be at most " + MAX_MESSAGE_LENGTH + " characters");
+            valid = false;
+        }
+
+        return valid;
+    }
+
+    private void refreshGrid() {
+        grid.setItems(messageService.getMessages());
+    }
+
+    private boolean hasUnsavedContent() {
+        return !name.isEmpty() || !email.isEmpty() || !phone.isEmpty() || !message.isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsavedContent()) {
+            return;
+        }
+
+        var action = event.postpone();
+
+        Dialog dialog = new Dialog();
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+
+        Button keepEditing = new Button("Keep editing", e -> dialog.close());
+        Button discard = new Button("Discard", e -> {
+            dialog.close();
+            action.proceed();
+        });
+
+        dialog.add(new Paragraph("You have unsaved changes. Do you want to discard them?"));
+        dialog.add(new HorizontalLayout(keepEditing, discard));
+        dialog.open();
+    }
+}
