+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+
+@SpringBootTest
+public class ContactViewTest extends SpringBrowserlessTest {
+
+    private int gridSize() {
+        return test(find(Grid.class).single()).size();
+    }
+
+    @Test
+    void headingAndAboutLink() {
+        navigate(ContactView.class);
+        assertEquals("Contact", test(find(H1.class).single()).getText());
+        assertTrue(find(RouterLink.class).withText("About").exists());
+    }
+
+    @Test
+    void sendingEmptyFormMarksAllRequiredFieldsInvalid() {
+        navigate(ContactView.class);
+        int before = gridSize();
+
+        Button send = find(Button.class).withText("Send").single();
+        test(send).click();
+
+        TextField name = find(TextField.class).withLabel("Name").single();
+        EmailField email = find(EmailField.class).withLabel("Email").single();
+        TextArea message = find(TextArea.class).withLabel("Message").single();
+
+        assertTrue(name.isInvalid());
+        assertEquals("Name is required", name.getErrorMessage());
+
+        assertTrue(email.isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+
+        assertTrue(message.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+
+        assertFalse(find(Notification.class).exists());
+        assertEquals(before, gridSize());
+    }
+
+    @Test
+    void invalidEmailFormat() {
+        navigate(ContactView.class);
+        EmailField email = find(EmailField.class).withLabel("Email").single();
+        test(email).setValue("not-an-email");
+
+        test(find(Button.class).withText("Send").single()).click();
+
+        assertTrue(email.isInvalid());
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+    }
+
+    @Test
+    void phoneAloneSatisfiesContactRequirement() {
+        navigate(ContactView.class);
+        test(find(TextField.class).withLabel("Name").single()).setValue("Jane");
+        test(find(TextField.class).withLabel("Phone").single()).setValue("12345");
+        test(find(TextArea.class).withLabel("Message").single()).setValue("Hello there");
+
+        test(find(Button.class).withText("Send").single()).click();
+
+        assertTrue(find(Notification.class).exists());
+        assertEquals("Message sent", test(find(Notification.class).single()).getText());
+    }
+
+    @Test
+    void messageTooLong() {
+        navigate(ContactView.class);
+        test(find(TextField.class).withLabel("Name").single()).setValue("Jane");
+        test(find(TextField.class).withLabel("Phone").single()).setValue("12345");
+        test(find(TextArea.class).withLabel("Message").single()).setValue("a".repeat(501));
+
+        test(find(Button.class).withText("Send").single()).click();
+
+        TextArea message = find(TextArea.class).withLabel("Message").single();
+        assertTrue(message.isInvalid());
+        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
+    }
+
+    @Test
+    void successfulSendClearsFormAndDisablesSendUntilEdit() {
+        navigate(ContactView.class);
+        int before = gridSize();
+        TextField name = find(TextField.class).withLabel("Name").single();
+        EmailField email = find(EmailField.class).withLabel("Email").single();
+        TextArea message = find(TextArea.class).withLabel("Message").single();
+
+        test(name).setValue("Jane");
+        test(email).setValue("jane@example.com");
+        test(message).setValue("Hello there");
+
+        Button send = find(Button.class).withText("Send").single();
+        test(send).click();
+
+        assertTrue(find(Notification.class).exists());
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", message.getValue());
+        assertFalse(send.isEnabled());
+
+        test(name).setValue("Bob");
+        assertTrue(send.isEnabled());
+
+        assertEquals(before + 1, gridSize());
+    }
+
+    @Test
+    void pressingEnterSendsTheForm() {
+        navigate(ContactView.class);
+        int before = gridSize();
+        test(find(TextField.class).withLabel("Name").single()).setValue("Jane");
+        test(find(EmailField.class).withLabel("Email").single()).setValue("jane@example.com");
+        test(find(TextArea.class).withLabel("Message").single()).setValue("Hello there");
+
+        fireShortcut(com.vaadin.flow.component.Key.ENTER);
+
+        assertTrue(find(Notification.class).exists());
+        assertEquals(before + 1, gridSize());
+    }
+
+    @Test
+    void messageListSurvivesLeavingAndReturning() {
+        navigate(ContactView.class);
+        int before = gridSize();
+        test(find(TextField.class).withLabel("Name").single()).setValue("Jane");
+        test(find(EmailField.class).withLabel("Email").single()).setValue("jane@example.com");
+        test(find(TextArea.class).withLabel("Message").single()).setValue("Hello there");
+        test(find(Button.class).withText("Send").single()).click();
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+
+        assertEquals(before + 1, gridSize());
+    }
+
+    @Test
+    void leavingWithContentAsksFirst() {
+        navigate(ContactView.class);
+        test(find(TextField.class).withLabel("Name").single()).setValue("Jane");
+
+        test(find(RouterLink.class).withText("About").single()).click();
+
+        assertTrue(find(Dialog.class).exists());
+        assertEquals(ContactView.class, getCurrentView().getClass());
